// ===================================================
// RE:BORN 復活アスリート図鑑 — 魂のアーカイブ
// ===================================================

// ---------- Athlete profiles ----------
export interface AthleteProfile {
  id: string;
  name: string;
  name_en: string;
  nationality: string;
  birthplace: string;
  birth_date: string;
  age: number;
  sport: string;
  family: string;
  upbringing: string;
  main_quote: string;
  sub_quote: string;
  achievements: string[];
  injury_detail: string;
  image_url: string | null;
  comeback_status: "in_progress" | "completed_success" | "completed_partial" | "retired";
}

export interface GoldenQuote {
  id: string;
  athlete_id: string;
  quote: string;
  context: string | null;
}

export interface Testimony {
  id: string;
  athlete_id: string;
  speaker_name: string;
  speaker_role: string;
  quote: string;
}

export interface StoryChapter {
  id: string;
  athlete_id: string;
  order: number;
  stage: "origin" | "despair" | "void" | "awakening" | "rebirth";
  title: string;
  body: string; // long-form markdown-ish
  year_label: string | null;
}

export interface InjuryRecord {
  id: string;
  athlete_id: string;
  body_region: string;
  injury_type: string;
  diagnosis: string;
  severity: number; // 1-10
  recovery_months: number;
  year_occurred: number;
  description: string;
  is_primary: boolean;
}

export interface QuizQuestion {
  id: string;
  athlete_id: string | null; // null = general
  quiz_type: "serious" | "coffee_break";
  difficulty: number;
  question_text: string;
  choices: string[];
  correct_index: number;
  rationale: string;
  encouragement: string;
}

export interface BodyCoord {
  region: string;
  x: number;
  y: number;
  z: number;
  label_ja: string;
}

