    body: "2020-21シーズン、デュラントはついにコートに戻った。復帰からわずか数試合で、世界中のバスケットボールファンは確信した——ケビン・デュラントは何も失っていない、と。\n\nアキレス腱断裂からの復帰者とは思えない滑らかな動き、精密なミドルレンジショット、そして変わらぬ得点感覚。2021年のプレーオフでは、ミルウォーキー・バックスとの第7戦で48得点を記録。延長戦で惜しくも敗れたが、あと数センチ足が後ろに下がっていればブザービーターの3ポイントが決まっていた。\n\n「アキレス腱断裂からこれほどのレベルで戻ってきた選手は、NBAの歴史に一人もいない。」——かつての恩師スティーブ・カー監督はそう語った。デュラントの復帰は、医学的にも常識を覆す出来事だった。",
    year_label: "2021年",
