    body: "京都府出身の高橋藍は、兄・塁の影響で小学生の頃にバレーボールを始めた。兄は一足先にバレーの世界で頭角を現し、その背中を追いかけるように藍もコートに立った。東山高校では春高バレーで全国の舞台を経験し、日本体育大学に進学。\n\n大学在学中にイタリア・セリエAのパドヴァへ渡るという大胆な決断を下した。守備の要であるリベロと、攻撃を両立する「攻守兼備」のアウトサイドヒッターとして、異国の地でその才能を開花させた。\n\n日本代表にも定着し、2024年のネーションズリーグでは銀メダルに貢献。24歳にして、日本バレーボール界の未来を担う存在となった。",
