    body: "復帰後のシーズン、高橋はセリエAでさらなる飛躍を遂げた。足首の負傷を乗り越え、以前よりも精度を増したプレーで日本代表を牽引。守備では相手のエースのスパイクを正面で受け止め、攻撃では多彩な角度からのスパイクで得点を量産した。\n\n「挫折は、自分がもっと強くなるための『溜め』だと思っている」——その信条の通り、怪我という「溜め」の期間に蓄えたエネルギーは、復帰後のプレーに余すところなく注ぎ込まれた。\n\n兄・塁と共にバレーの道を歩んできた高橋藍。コートの外で費やした時間が、コート上のパフォーマンスを何段階も引き上げた。京都の少年は今、世界の舞台で日本バレーの未来を体現している。",
