    body: "鳥取県米子市。入江聖奈がボクシングを始めたきっかけは、漫画「がんばれ元気」だった。主人公が拳一つで立ち向かう姿に心を奪われ、小学生の時に地元のジムの門を叩いた。\n\nもう一つの大きな特徴は、カエルへの深い愛情だ。自宅でカエルを飼い、その生態を観察することが日課。「カエルはジャンプする瞬間まで、じっと力を溜めている。私もそうありたい」——独特の感性が、彼女のボクシングスタイルにも影響を与えた。\n\n地道な反復練習を誰よりも愛し、同じパンチを何千回も繰り返す。派手さはないが、確実に相手の急所を捉える精密なボクシング。日本体育大学に進学し、アマチュアボクシング界でその名を知られるようになった。",
