    body: "兵庫県伊丹市出身の田中将大は、駒大苫小牧高校のエースとして夏の甲子園で連覇を達成。2006年の決勝では早稲田実業の斎藤佑樹と引き分け再試合を演じ、日本中を熱狂させた。\n\n楽天ゴールデンイーグルスに入団後、その実力は急速に開花。2013年には24勝0敗という前人未到の記録を打ち立て、チームを球団初の日本一に導いた。負けない投手——その異名は、田中の精神力の強さを物語っていた。\n\n2014年、満を持してMLBのニューヨーク・ヤンキースへ。7年総額1億5500万ドルという破格の契約で、世界最高の舞台へ挑んだ。",
