    body: "2014年7月、ヤンキースでの1年目。田中の右肘内側側副靭帯が部分断裂した。通常であればトミー・ジョン手術が必要な状態。手術をすれば復帰まで最低1年半。しないまま投げ続ければ、完全断裂のリスクが常につきまとう。\n\n24連勝を支えた剛腕。その源泉であった「力任せの投球」が、肘という最も脆い関節を蝕んでいた。メジャーリーグの過密日程、硬いマウンド、そして150km/hを超える速球——すべてが肘への負担を加速させていた。\n\n「投げることが怖くなった瞬間があった」——後に田中はそう振り返っている。投手にとって、腕を振ることへの恐怖は存在そのものの危機だった。",
