    body: "愛知県岡崎市出身の石川祐希は、バレーボール一家に生まれた。姉も妹の真佑もバレーボール選手。中学時代から全国の頂点を知り、星城高校では春高バレー連覇を達成。中央大学在学中の2014年、わずか19歳でイタリア・セリエAのラティーナに留学した。\n\n「世界で一番になりたいなら、世界で一番厳しい環境に身を置くべきだ」——この信念が、彼を異国の地に向かわせた。イタリアリーグは世界最高峰のバレーボールリーグ。圧倒的なフィジカルとスピードを持つ選手たちの中で、石川は自らの限界を何度も突き破っていった。\n\nやがて日本代表の主将にも選ばれ、名実ともに日本バレーボール界のエースとなった。",
