    body: "2023年シーズン中、腰痛が悪化し、下肢にも負傷が広がった。バレーボール選手にとって腰はジャンプの起点であり、スパイクの軸。その腰が機能しなくなることは、選手の根幹が揺らぐことを意味した。\n\n日本代表の主将としての重圧も重なった。チームを率いる責任、結果を出さなければならないプレッシャー。身体の痛みと精神的な負荷が同時に襲いかかる中、石川はコートを離れることを余儀なくされた。\n\n「怪我で休んでいる間、悔しさで眠れない夜が何度もあった」——イタリアの自宅で一人、天井を見つめる夜が続いた。",
