    body: "宮城県仙台市。福原愛は3歳9ヶ月でラケットを握り、その天才的な才能はすぐに日本中の注目を集めた。テレビに映る幼い少女は、負けると大粒の涙を流しながらも、決して練習を辞めようとしなかった。「泣き虫愛ちゃん」——その愛称は日本中の家庭に広まった。\n\n母・千代の指導は厳しかった。何百球、何千球と打ち続ける毎日。しかしその厳しさの裏には深い愛情があった。泣きながらも打ち返す少女の姿に、日本中が心を動かされた。\n\n10代で全日本選手権を制覇し、中国スーパーリーグにも参戦。中国語を流暢に操り、中国でも「瓷娃娃（磁器の人形）」と呼ばれて愛された。卓球を通じて、国境を越えた架け橋となる存在だった。",
