    body: "千葉県柏市。9歳で脊髄腫瘍により下半身の自由を失った国枝慎吾は、母の勧めで車いすテニスと出会った。車いすを「足」のように操る天才的なチェアワーク。それは健常者のフットワークを超える芸術だった。\n\n「車いすは僕にとっての『足』。これをどう乗りこなすかが僕のテニス」\n\n彼のチェアワークは革命的だった。従来の車いすテニス選手が2回漕いで追いつく距離を、国枝は1回の漕ぎで到達した。車いすと身体が一体化する感覚——それを極限まで磨き上げた結果、23歳で世界ランク1位に到達。グランドスラムのタイトルを次々と奪い、「車いすテニスの王者」として君臨した。\n\n「俺は最強だ！」——自らを鼓舞するこの叫びは、彼のアイデンティティそのものだった。",
