    body: "2021年東京パラリンピック。自国開催の大舞台で、国枝慎吾は完全復活を遂げた。改造したバックハンドは以前よりも鋭く、メンタルの改革は試合中の冷静さに表れていた。\n\n決勝。劣勢の場面でも崩れない精神力。かつてのように感情的にならず、一球一球を丁寧に積み重ねる新しい国枝がそこにいた。逆転で金メダルを獲得した瞬間、車いすの上で天を仰いだ。\n\n「怪我で負け続けた時、僕は初めて自分の弱さを認めて、強くなれた」\n\n弱さを認めたことで、逆に誰よりも強くなった。「俺は最強だ」の叫びは、虚勢ではなく、弱さを乗り越えた者だけが放てる本物の自信に変わっていた。\n\n「彼は一度死んで、また蘇った。今の彼は以前よりも手が付けられないほど強い。」——ライバルたちの言葉が、それを証明していた。",
