    body: "宮城県気仙沼市。早稲田大学に進学した谷真海（旧姓・佐藤）は、チアリーダー部に所属し、大学生活を謳歌していた。活発な性格で、スポーツを通じて自分を表現することに喜びを感じていた。\n\n応援団としてグラウンドに立ち、声を張り上げ、チームメイトと笑い合う日々。将来への希望に満ちた20歳の女性がそこにいた。運動神経は抜群で、どんなスポーツでも器用にこなす——誰もが認める「太陽のような存在」だった。\n\n故郷の気仙沼は、海の幸に恵まれた穏やかな港町。両親の温かい愛情に包まれて育った少女は、世界の舞台に立つことなど想像もしていなかった。しかし運命は、彼女に想像を超える試練と、想像を超える栄光を同時に用意していた。",
