    title: "バスケ一家の覚悟——NBAを目指して",
    body: "香川県三木町。父も母も元バスケットボール選手という環境で育った渡邊雄太は、幼少期からボールと共に生きてきた。しかし彼が持っていたのは「才能」ではなく「覚悟」だった。\n\n日本のバスケットボールは世界との距離が遠い時代。それでも渡邊は「世界で通用する選手になる」と決意し、高校卒業後にアメリカの大学に進学した。言葉の壁、文化の違い、圧倒的なフィジカルの差——全てが壁だった。\n\nジョージ・ワシントン大学で4年間を過ごし、アメリカのバスケットボールを肌で学んだ。NBAの舞台に立つという夢は、まだ遠い場所にあった。しかし彼は知っていた——才能がないなら、誰よりも努力するしかないと。\n\n「才能がないなら、誰よりも早く体育館に来て、誰よりも遅く帰るしかない」——その言葉を体現する日々が始まった。",
