    title: "完全なる暗闇——光を失った日",
    body: "視力の低下は止まらなかった。視野はどんどん狭まり、最終的に完全に光を失った。それは段階的な絶望だった。今日見えているものが、明日には見えなくなるかもしれない。その恐怖の中で生きる日々は、想像を絶するものだった。\n\n健常者としてトップを目指していた夢は、静かに、しかし確実に閉ざされていった。大学を卒業後、宇宙は一般企業に就職した。水泳からは離れた。「もう、泳ぐ意味がない」——そう思った時期があった。\n\n暗闇の中で、かつて水の中で感じていた自由の感覚が、記憶の奥底から消えていくような恐怖。見えない世界で、自分が何者なのかすらわからなくなっていった。",
