    body: "神奈川県横浜市。早くから海外でプレーすることを志した航は、中学時代から自ら「分析ノート」を作成していた。対戦相手の動き、自分のプレーの改善点、戦術のアイデア——全てをノートに記録し、PDCAサイクルを自分で回す少年だった。\n\n湘南ベルマーレでプロキャリアをスタートさせた後、浦和レッズを経てベルギー、そしてドイツ・ブンデスリーガのシュトゥットガルトへ移籍。ブンデスリーガでは「デュエル王」（対人戦勝率トップ）を2度獲得。球際の強さと戦術眼で、ドイツの屈強な選手たちを凌駕した。\n\n日本代表でも主将を任され、チームの心臓として君臨。2022年カタールW杯では、日本代表を率いてドイツ、スペインを撃破する歴史的な快挙を成し遂げる立役者となった。",
    year_label: "〜2022",
