    body: "2022年カタールW杯開幕の直前、航は脳震盪を起こした。サッカーにおいて脳震盪は、一度の衝撃で選手生命を脅かしかねない深刻な負傷だ。\n\n頭痛、めまい、集中力の低下。医師からは十分な回復期間を取るよう勧告された。しかし、W杯の開幕は待ってくれない。日本代表の主将が、最も大切な大会の直前に離脱するかもしれない——その不安がチーム全体に広がった。\n\nさらに、所属チームでのポジション争いも激化していた。控えに回される期間があり、試合勘を失う恐怖と戦わなければならなかった。「準備がすべて」と語る男にとって、準備ができない状況は最大の危機だった。",
