    body: "福岡県福岡市。幼少期から並外れた肩の強さを見せた由岐子は、ソフトボールと出会い、その才能を爆発させた。九州特有の厳しい指導環境は、少女の精神力を鍛え上げ、「日本一の右腕」へと成長させた。\n\n2004年アテネ五輪。予選リーグから決勝まで、上野は驚異的な413球を一人で投げ抜いた。その姿は「鉄腕」と称され、日本中を熱狂させた。チームは銅メダルに終わったが、上野の名は世界に轟いた。\n\n2008年北京五輪では、その集大成を見せる。再び413球に匹敵する力投で、日本をソフトボール初の金メダルに導いた。宿敵アメリカを決勝で破った瞬間、上野は仲間と抱き合って泣いた。26歳にして、すでに伝説だった。",
