    body: "口をワイヤーで固定され、食事もままならない中、上野は止まらなかった。投げられない。食べられない。しかし、足は動く——そう判断した上野は、顎の回復を待つ間、下半身と体幹のトレーニングに全力を注いだ。\n\n「顎を折ったあの日、私のソフトボール人生はリセットされ、新しく始まった」\n\nリハビリの過程で、上野は37歳の自分の体と徹底的に向き合った。若い頃のようなパワーピッチングではなく、円熟した制球力と変化球の精度を武器にする新しい投球スタイル。怪我が、彼女を「進化」させていた。\n\n宇津木麗華監督は、その姿をこう表現した。「彼女はサイボーグのようだ。顎を折っても、マウンドに戻ることしか考えていなかった。」",
