    body: "離脱期間中、錦織はコートに立てない日々の中で、意外な発見をした。テニスへの愛情が、以前よりも深くなっていたのだ。\n\n「休んでいる間に、テニスがもっと好きになった。それだけで復帰の価値がある」\n\nマイケル・チャンコーチとのオンラインミーティングを重ね、戦術の研究に没頭した。体を動かせない間、頭の中では何百試合もシミュレーションを繰り返した。かつては「勝たなければならない」というプレッシャーが支配していたテニスが、純粋な「好き」に立ち返った瞬間だった。\n\nリハビリの過程で、錦織は体の使い方を根本から見直した。若い頃のような無理な動きを減らし、効率的なフットワークと、培ってきたテニスIQで勝負する新しいスタイル。手術のたびにアップデートされていく自分を感じていた。",
