    body: "リハビリ施設で、藤原は車いすバスケットボールに出会った。車いす同士が激しくぶつかり合い、コートを縦横無尽に駆ける選手たち。その激しさに、一目で心を奪われた。\n\n「車いすバスケの選手たちが、こんなにカッコいいとは思わなかった」\n\nその日から、リハビリの目的が変わった。「歩けるようになる」から「漕げるようになる」へ。車いすは「不自由の象徴」ではなく、「新しい可能性の象徴」に変わった瞬間だった。\n\n最初はまともにボールも掴めなかった。車いすの操作もおぼつかない。しかし、かつてスポーツに注いだ情熱が再び燃え上がり、毎日欠かさず体育館に通い続けた。同じ障害を持つチームメイトたちが、彼女を励まし、笑わせ、時に厳しく叱った。\n\n「車いすは私にとっての『かっこいい戦闘機』」——その言葉には、障害を受け入れ、超えていく決意が込められていた。",
