    body: "2011年3月11日、東日本大震災。岩手県陸前高田市に暮らしていた9歳の佐々木朗希は、津波で父と祖父母を失った。家も流された。住み慣れた街は跡形もなく消え去り、少年は一夜にして全てを失った。\n\n避難所での生活。母・陽子は、三人の息子を一人で育てる決意を固めた。朗希は、悲しみを表に出さず、黙々と野球を続けた。ボールを握る手だけが、彼を現実に繋ぎ止めていた。\n\n大船渡高校に進学した朗希は、その才能を爆発させる。最速163km/hの剛速球は、高校球児の域を超えていた。しかし、國保監督はあえて県大会決勝で朗希を登板させなかった。「将来のために」——その決断は賛否を呼んだが、後に正しさが証明される。",
