    body: "2022年4月10日。ロッテ対オリックス戦。佐々木朗希は、プロ野球史に永遠に刻まれる偉業を達成した。完全試合。しかもそれだけではない。13者連続奪三振という世界記録。19奪三振も日本タイ記録だった。\n\n165km/hのストレートと、140km/h台のフォークボール。打者たちは、ただ見送るか空振りすることしかできなかった。28個のアウトのうち、19が三振。これは人間の投球ではなく、もはや芸術だった。\n\n試合後、朗希はこう語った。「野球は、僕を支えてくれた人たちへの恩返し。」震災で全てを失った少年が、待つことを学び、体を作り直し、そして日本の野球史を塗り替えた。\n\n2023年のWBCでは日本代表の一員として優勝に貢献。世界の強打者たちをねじ伏せる姿に、陸前高田の母は涙を流した。",
