    body: "バレーボール選手にとって、指の怪我は日常茶飯事だ。しかし木村の場合、骨折した指でテーピングを巻き、そのまま試合に出続けた。膝や腰の慢性的な痛みにも、彼女は顔を曇らせなかった。\n\n「指を折っても、心は折れなかった」——その言葉の裏には、折れそうな心を必死で支える日々があった。\n\n主将に任命されてからは、精神的な負担がさらに重くのしかかった。チームの結果が全て自分の責任に感じられる。日本代表の「顔」として、メディアの注目も集中する。笑顔を求められ、強さを求められ、完璧を求められる毎日。彼女の細い肩に、日本の女子バレーの全てが載っていた。",
