    title: "雪山に育まれたテクニシャン",
    body: "富山県富山市。日本海側の豪雪地帯に生まれた大江光は、幼少期から雪山が遊び場だった。スキーとスノーボードを自然に覚え、特にハーフパイプでは卓越した技術を見せた。\n\n柔らかいボードさばきと、空中での美しい姿勢制御。彼女のエアは「芸術的」と評され、ユース五輪では金メダルを獲得。X Gamesでも入賞を果たし、日本女子ハーフパイプの未来を背負う存在として期待された。\n\n雪山に生まれ、雪山に育てられた少女。彼女にとってスノーボードは遊びであり、表現であり、生きることそのものだった。",
