    title: "両膝の前十字靭帯断裂——最悪の怪我",
    body: "スノーボーダーにとって、前十字靭帯（ACL）の断裂は最悪の怪我だ。着地の衝撃を吸収する膝が壊れれば、エアを飛ぶことはできない。大江は、その最悪の怪我を両膝で経験した。\n\n最初は右膝。大会での着地に失敗し、膝がグラリと崩れた。手術とリハビリを経て復帰したが、今度は左膝。繰り返されるACL断裂に、彼女は絶望した。\n\n「もう膝がもたない」「スノーボードは諦めた方がいい」——医師からも周囲からも、そう言われた。両膝の靭帯が破壊された20代の女性に、高速でパイプを滑り、空中で回転するスポーツを続ける未来はないように思えた。",
