    title: "ボロボロの膝で掴んだ世界の舞台",
    body: "再び世界の舞台に立った大江光。両膝の前十字靭帯を断裂し、数回の手術を経た体で、彼女は華麗なエアを飛び続けている。\n\n「板に乗る恐怖より、板に乗れない寂しさの方が大きかった」——その言葉が全てを物語る。恐怖を乗り越えるのは勇気ではなく、スノーボードへの愛情だった。\n\nリハビリで得た体幹の強さ、着地フォームの改善、そしてメンタルの成熟。壊れるたびに強くなる彼女の姿は、「ボロボロの膝」に新しい意味を与えた。それは弱さの象徴ではなく、何度でも立ち上がった証だ。\n\n富山の雪山で育ったテクニシャンは、両膝の痛みと共に、今日も空を舞っている。壊れたパズルから作り上げた新しい自分で。",
